	CanceledAt         *time.Time `json:"canceled_at,omitempty"`
	CreatedAt          time.Time  `json:"created_at"`
}

// Line is one line of an invoice. A negative UnitAmount is a credit.
type Line struct {
	Description string `json:"description"`
	Quantity    int64  `json:"quantity"`
	UnitAmount  int64  `json:"unit_amount"`
}

// Amount is the line's quantity times its unit amount.
func (l Line) Amount() int64 { return l.Quantity * l.UnitAmount }

// InvoiceStatus is an invoice's state.
type InvoiceStatus string

// Invoice states.
const (
	InvoiceOpen InvoiceStatus = "open"
	InvoicePaid InvoiceStatus = "paid"
	InvoiceVoid InvoiceStatus = "void"
)

// Invoice is a bill to a customer.
type Invoice struct {
	ID              string         `json:"id"`
	OrgID           string         `json:"org_id"`
	CustomerID      string         `json:"customer_id"`
	SubscriptionID  string         `json:"subscription_id,omitempty"`
	Currency        money.Currency `json:"currency"`
	Lines           []Line         `json:"lines"`
	DiscountPercent int            `json:"discount_percent"`
	TaxRateBP       int            `json:"tax_rate_bp"`
	Status          InvoiceStatus  `json:"status"`
	PeriodStart     *time.Time     `json:"period_start,omitempty"`
	PeriodEnd       *time.Time     `json:"period_end,omitempty"`
	CreatedAt       time.Time      `json:"created_at"`
	PaidAt          *time.Time     `json:"paid_at,omitempty"`
	VoidedAt        *time.Time     `json:"voided_at,omitempty"`
}

// PaymentStatus is a payment attempt's result.
type PaymentStatus string

// Payment results.
const (
	PaymentSucceeded PaymentStatus = "succeeded"
	PaymentFailed    PaymentStatus = "failed"
)

// Payment is one attempt to charge an invoice.
type Payment struct {
	ID          string         `json:"id"`
	OrgID       string         `json:"org_id"`
	InvoiceID   string         `json:"invoice_id"`
	Amount      int64          `json:"amount"`
	Currency    money.Currency `json:"currency"`
	Status      PaymentStatus  `json:"status"`
	FailureCode string         `json:"failure_code,omitempty"`
	GatewayRef  string         `json:"gateway_ref,omitempty"`
	CreatedAt   time.Time      `json:"created_at"`
}

// UsageRecord is usage reported for a subscription to a metered plan.
type UsageRecord struct {
	ID             string    `json:"id"`
	OrgID          string    `json:"org_id"`
	SubscriptionID string    `json:"subscription_id"`
	Quantity       int64     `json:"quantity"`
	At             time.Time `json:"at"`
	CreatedAt      time.Time `json:"created_at"`
}

// WebhookEndpoint is a URL of the organization's that receives events.
type WebhookEndpoint struct {
	ID     string   `json:"id"`
	OrgID  string   `json:"org_id"`
	URL    string   `json:"url"`
	Events []string `json:"events"` // event types, or "*" for all
	// Secret signs the deliveries (webhooks.Sign).
	Secret         string    `json:"secret"`
	Enabled        bool      `json:"enabled"`
	DisabledReason string    `json:"disabled_reason,omitempty"`
	CreatedAt      time.Time `json:"created_at"`
}

// Event is something that happened in an organization, sent to its webhook endpoints.
type Event struct {
	ID        string          `json:"id"`
	OrgID     string          `json:"org_id"`
	Type      string          `json:"type"`
	Data      json.RawMessage `json:"data"`
	CreatedAt time.Time       `json:"created_at"`
}

// DeliveryStatus is a webhook delivery's state.
type DeliveryStatus string

// Delivery states.
const (
	DeliveryPending   DeliveryStatus = "pending"
	DeliverySucceeded DeliveryStatus = "succeeded"
	DeliveryFailed    DeliveryStatus = "failed"
)

// Delivery is the sending of one event to one endpoint.
type Delivery struct {
	ID             string         `json:"id"`
	OrgID          string         `json:"org_id"`
	EndpointID     string         `json:"endpoint_id"`
	EventID        string         `json:"event_id"`
	Status         DeliveryStatus `json:"status"`
	Attempts       int            `json:"attempts"`
	NextAttemptAt  *time.Time     `json:"next_attempt_at,omitempty"`
	LastAttemptAt  *time.Time     `json:"last_attempt_at,omitempty"`
	ResponseStatus int            `json:"response_status,omitempty"`
	Error          string         `json:"error,omitempty"`
	CreatedAt      time.Time      `json:"created_at"`
}
// Package billing is invoice arithmetic and billing periods. It holds no state.
package billing

import (
	"time"

	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
)

// Totals are the amounts shown on an invoice, in the invoice currency's minor unit.
type Totals struct {
	Subtotal int64 `json:"subtotal"`
	Discount int64 `json:"discount"`
	Tax      int64 `json:"tax"`
	Total    int64 `json:"total"`
}

// Compute returns an invoice's totals: the sum of its lines, the discount (DiscountPercent of the subtotal), and tax at the
// invoice's rate on the subtotal after the discount. The discount and the tax are each rounded half away from zero to a
// whole minor unit.
func Compute(inv store.Invoice) Totals {
	var subtotal int64
	for _, l := range inv.Lines {
		subtotal += l.Amount()
	}
	discount := money.Percent(subtotal, inv.DiscountPercent)
	taxable := subtotal - discount
	tax := money.BasisPoints(taxable, inv.TaxRateBP)
	return Totals{Subtotal: subtotal, Discount: discount, Tax: tax, Total: taxable + tax}
}

// AddInterval returns t moved forward by one billing interval: a month or a year.
func AddInterval(t time.Time, iv store.Interval) time.Time {
	if iv == store.Yearly {
		return t.AddDate(1, 0, 0)
	}
	return t.AddDate(0, 1, 0)
}
// Package money handles amounts of money. An amount is an int64 count of its currency's minor unit (cents for USD), never a
// float.
package money

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
)

// Currency is an ISO 4217 currency code.
type Currency string

// The currencies Tally bills in.
const (
	USD Currency = "USD"
	EUR Currency = "EUR"
	GBP Currency = "GBP"
	JPY Currency = "JPY"
	KWD Currency = "KWD"
)

var symbols = map[Currency]string{USD: "$", EUR: "€", GBP: "£", JPY: "¥", KWD: "KWD "}

// Valid reports whether c is a currency Tally bills in.
func (c Currency) Valid() bool {
	_, ok := symbols[c]
	return ok
}

// ErrInvalidAmount is returned for an amount that cannot be read.
var ErrInvalidAmount = errors.New("invalid amount")

// ParseMajor reads an amount a person typed in major units ("12.50", "7") and returns it in minor units.
func ParseMajor(s string, c Currency) (int64, error) {
	if !c.Valid() {
		return 0, fmt.Errorf("%w: unknown currency %q", ErrInvalidAmount, c)
	}
	s = strings.TrimSpace(s)
	whole, frac, hasDot := strings.Cut(s, ".")
	if whole == "" || (hasDot && frac == "") || len(frac) > 2 {
		return 0, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
	}
	for _, r := range whole + frac {
		if r < '0' || r > '9' {
			return 0, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
		}
	}
	for len(frac) < 2 {
		frac += "0"
	}
	n, err := strconv.ParseInt(whole+frac, 10, 64)
	if err != nil {
		return 0, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
	}
	return n, nil
}

// Format renders an amount for people: "$1,234.50", "-€0.99".
func Format(amount int64, c Currency) string {
	sign := ""
	if amount < 0 {
		sign, amount = "-", -amount
	}
	whole, frac := amount/100, amount%100
	return fmt.Sprintf("%s%s%s.%02d", sign, symbols[c], group(whole), frac)
}

// group writes n with a comma between each group of three digits.
func group(n int64) string {
	s := strconv.FormatInt(n, 10)
	var b strings.Builder
	for i, r := range s {
		if i > 0 && (len(s)-i)%3 == 0 {
			b.WriteByte(',')
		}
		b.WriteRune(r)
	}
	return b.String()
}

// Percent returns pct percent of amount, rounded half away from zero to a whole minor unit.
func Percent(amount int64, pct int) int64 { return divRound(amount*int64(pct), 100) }

// BasisPoints returns bp basis points (hundredths of a percent) of amount, rounded half away from zero.
func BasisPoints(amount int64, bp int) int64 { return divRound(amount*int64(bp), 10000) }

// divRound divides and rounds half away from zero.
func divRound(num, den int64) int64 {
	if (num < 0) != (den < 0) {
		return -((abs(num) + abs(den)/2) / abs(den))
	}
	return (abs(num) + abs(den)/2) / abs(den)
}

func abs(v int64) int64 {
	if v < 0 {
		return -v
	}
	return v
}

