// parseTiers reads tiers' amounts in major units and returns them in minor units. A bad amount is an ErrInvalidTiers.
func parseTiers(in []tierIn, c money.Currency) ([]store.Tier, error) {
	out := make([]store.Tier, 0, len(in))
	for _, t := range in {
		unit, err := money.ParseMajor(t.UnitAmount, c)
		if err != nil {
			return nil, fmt.Errorf("%w: %v", store.ErrInvalidTiers, err)
		}
		var flat int64
		if t.FlatAmount != "" {
			if flat, err = money.ParseMajor(t.FlatAmount, c); err != nil {
				return nil, fmt.Errorf("%w: %v", store.ErrInvalidTiers, err)
			}
		}
		out = append(out, store.Tier{UpTo: t.UpTo, UnitAmount: unit, FlatAmount: flat})
	}
	return out, nil
}

