cat >> internal/billing/billing_test.go <<'EOF'

func TestTieredAmount(t *testing.T) {
	upTo := func(n int64) *int64 { return &n }
	tiers := []store.Tier{
		{UpTo: upTo(10), UnitAmount: 100, FlatAmount: 200},
		{UpTo: upTo(20), UnitAmount: 80, FlatAmount: 500},
		{UpTo: nil, UnitAmount: 50},
	}
	for _, c := range []struct {
		mode store.TiersMode
		q    int64
		want int64
	}{
		{store.Graduated, 0, 0},
		{store.Graduated, 5, 5*100 + 200},
		{store.Graduated, 10, 10*100 + 200},
		{store.Graduated, 15, 10*100 + 200 + 5*80 + 500},
		{store.Graduated, 20, 10*100 + 200 + 10*80 + 500},
		{store.Graduated, 25, 10*100 + 200 + 10*80 + 500 + 5*50},
		{store.Volume, 0, 0},
		{store.Volume, 5, 5*100 + 200},
		{store.Volume, 10, 10*100 + 200},
		{store.Volume, 11, 11*80 + 500},
		{store.Volume, 20, 20*80 + 500},
		{store.Volume, 21, 21 * 50},
	} {
		if got := TieredAmount(tiers, c.mode, c.q); got != c.want {
			t.Errorf("TieredAmount(%s, %d) = %d, want %d", c.mode, c.q, got, c.want)
		}
	}
	if got := TieredAmount(nil, store.Graduated, 5); got != 0 {
		t.Errorf("no tiers = %d, want 0", got)
	}
}
EOF
