func TestTieredUsageIsBilledAsOneLine(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	upTo := int64(10)
	tiers := []store.Tier{{UpTo: &upTo, UnitAmount: 100, FlatAmount: 200}, {UnitAmount: 50}}
	p, err := e.Store.CreatePlan(store.Plan{OrgID: e.Acme.ID, Name: "API calls", Currency: money.USD, Interval: store.Monthly,
		UsageType: store.Metered, TiersMode: store.Graduated, Tiers: tiers}, e.Clock.Now())
	if err != nil {
		t.Fatal(err)
	}
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	start, end := sub.CurrentPeriodStart, sub.CurrentPeriodEnd
	for _, u := range []struct {
		q  int64
		at time.Time
	}{{12, start}, {3, start.Add(48 * time.Hour)}} {
		if _, err := e.Store.AddUsage(e.Acme.ID, sub.ID, u.q, u.at, e.Clock.Now()); err != nil {
			t.Fatal(err)
		}
	}
	// 15 units graduated: 10 at 100 plus the flat 200, then 5 at 50 = 1450.
	e.Clock.Set(end)
	if _, err := e.Subs.RenewDue(ctx); err != nil {
		t.Fatal(err)
	}
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != 1 || len(invs[0].Lines) != 1 {
		t.Fatalf("invoices = %+v", invs)
	}
	if l := invs[0].Lines[0]; l.Quantity != 1 || l.UnitAmount != 1450 || !strings.HasPrefix(l.Description, "API calls") {
		t.Fatalf("line = %+v", l)
	}
	// The next period has no usage: renewing it makes no invoice.
	renewed, _ := e.Store.Subscription(e.Acme.ID, sub.ID)
	e.Clock.Set(renewed.CurrentPeriodEnd)
	if _, err := e.Subs.RenewDue(ctx); err != nil {
		t.Fatal(err)
	}
	if invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID}); len(invs) != 1 {
		t.Fatalf("a period without usage was invoiced: %+v", invs)
	}
}

args.old_string:
		t.Fatalf("invoices = %+v (usage at the period's end belongs to the next period)", invs)
	}
}

args.new_string:
		t.Fatalf("invoices = %+v (usage at the period's end belongs to the next period)", invs)
	}
}

