// tierIn is a tier as it is sent: its amounts are in major units, as strings. FlatAmount may be left out (0).
// UpTo is kept raw so that anything other than null or a whole number is an invalid tier (422), not a bad body (400).
type tierIn struct {
	UpTo       json.RawMessage `json:"up_to"`
	UnitAmount string          `json:"unit_amount"`
	FlatAmount string          `json:"flat_amount"`
}

// parseUpTo reads a tier's up_to: nil (no upper limit) or a positive whole number. Anything else is an ErrInvalidTiers.
func parseUpTo(raw json.RawMessage) (*int64, error) {
	if len(raw) == 0 || string(raw) == "null" {
		return nil, nil
	}
